class Combined2Agent:
    def __init__(self, data=None):
        self.chains = {
            "better": lambda: EvidenceAgent(HealthScope(GuardedAgent(BetterAgent())), data),
            "combined": lambda: EvidenceAgent(GuardedAgent(CombinedCore()), data, questions=False),
        }
        self.case_id = self.chosen = self.delegate = None

    def __getattr__(self, name):
        if name in ("chains", "case_id", "chosen", "delegate"):
            raise AttributeError(name)
        return getattr(self.delegate, name)
        return lambda: EvidenceAgent(GuardedAgent(ReciprocalAgent()), data)
    if name == "simplify":
        return lambda: EvidenceAgent(GuardedAgent(SimplifyAgent()), data)
    if name == "final":
        return lambda: EvidenceAgent(GuardedAgent(FinalAgent()), data, questions=False)
    if name == "final_match":
        return lambda: EvidenceAgent(GuardedAgent(FinalAgent(match=1.0)), data, questions=False)
    if name == "combined":  # v6-petra: Alex's final agent moves + the listener's supplier model
        return lambda: EvidenceAgent(GuardedAgent(CombinedAgent()), data, questions=False)
    if name == "combined2":  # v8-petra: router - index-clause cases without health at stake -> combined, else better
        return lambda: Combined2Agent(data)  # each route builds its own evidence / guard chain
    if name == "listener":  # v4-petra: supplier model + packages, inside the guard and the evidence layer
        return lambda: EvidenceAgent(GuardedAgent(ListenerAgent()), data)
    if name == "playbook":
        return lambda: EvidenceAgent(GuardedAgent(PlaybookAgent(SimplifyAgent())), data)
